package com.zartivo.inputfinder;
import android.app.Activity; import android.os.Bundle; import android.media.tv.TvInputInfo; import android.media.tv.TvInputManager; import android.widget.*; import android.content.*; import java.util.List;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this); l.setOrientation(1); l.setPadding(24,24,24,24); TextView t=new TextView(this); t.setTextSize(16); Button c=new Button(this); c.setText("Copy report"); ScrollView s=new ScrollView(this); s.addView(t); l.addView(c); l.addView(s,new LinearLayout.LayoutParams(-1,0,1)); String r;
 try {TvInputManager m=(TvInputManager)getSystemService(TV_INPUT_SERVICE); if(m==null)r="TvInputManager unavailable."; else {List<TvInputInfo> xs=m.getTvInputList(); StringBuilder q=new StringBuilder("Inputs returned: "+xs.size()+"\n\n"); for(TvInputInfo x:xs){q.append("Label: "+x.loadLabel(this)+"\nID: "+x.getId()+"\nType: "+x.getType()+"\nComponent: "+x.getServiceInfo().packageName+"/"+x.getServiceInfo().name+"\n\n");} r=q.toString(); if(xs.isEmpty())r+="No inputs returned. Firmware may restrict access.";}} catch(SecurityException e){r="Access denied (likely privileged API restriction):\n"+e;}catch(Throwable e){r="Error:\n"+e;} final String report=r; t.setText(report); c.setOnClickListener(v->{ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("TV Input report",report));Toast.makeText(this,"Copied",Toast.LENGTH_SHORT).show();}); setContentView(l);}
}
